            # Compute the cross terms: occurrences that start in left s_{k-1} and end in right s_{k-1}
            cross_count = 0
            # For each possible split of w into a prefix and suffix
            for l in range(1, len_w):
                prefix = w[:l]
                suffix = w[l:]
                # Count occurrences of prefix at the end of s_{k-1}
                # Count occurrences of suffix at the start of s_{k-1}
                # The product of these counts gives the number of cross terms for this split
                # But we need to count how many times prefix appears at the end of s_{k-1} and suffix at the start

                # To compute the number of times prefix appears at the end of s_{k-1}, we can use the following:
                # The number of occurrences of prefix in s_{k-1} that end at the last position of s_{k-1}
